#include <bits/stdc++.h>
#include "atcoder/modint"

using namespace std;
using ll = long long;
using mint = atcoder::modint998244353;

int main() {
  int n;
  cin >> n;
  vector<int> a(n);
  for(auto &v : a) cin >> v;
  vector<int> d(11);
  for(int i = 0; i < n; i++) {
    d[to_string(a[i]).size()]++;
  }
  mint res = 0;
  vector<mint> p10(11, 1);
  for(int i = 1; i <= 10; i++) p10[i] = p10[i - 1] * 10;
  for(int i = 0; i < n; i++) {
    res += mint(a[i]) * i;
    d[to_string(a[i]).size()]--;
    for(int j = 1; j <= 10; j++) {
      res += p10[j] * a[i] * d[j];
    }
  }
  cout << res.val() << endl;
}

#include <iostream>
#include <array>
#include <ranges>
#include <atcoder/modint>

int main() {
    using namespace std;
    using modint = atcoder::static_modint<998244353>;
    unsigned N;
    cin >> N;
    modint ans{}, prefix_sum{};
    for (unsigned i{}, A; i < N; ++i) {
        cin >> A;
        // 10^k <= A であるような最大の 10^k を求める
        unsigned pow_ten_floor{1};
        for (const auto pow_ten : array<unsigned, 4>{10, 100, 10000, 100000000} | views::reverse)
            if (A / pow_ten >= pow_ten_floor)
                pow_ten_floor *= pow_ten;

        // 答えに A[i] * i + 10^(k+1)S を足す
        ans += modint::raw(A) * i + prefix_sum * pow_ten_floor * 10;

        // S に A[i] を足す
        prefix_sum += A;
    }
    cout << ans.val() << endl;
    return 0;
}
